/* Generated by scripts/a21_images/slice_sheets.py - do not edit by hand.
   Pictures for the A2.1 words (Kapitel 1-6), keyed by "chapter|headword".
   Loaded after data_a21_vocab.js; it only fills cards that still have no picture. */
window.A2_VOCAB_21_IMAGES = {};

(function applyA21Images(){
  if(!Array.isArray(window.BOOK0)) return;
  window.BOOK0.forEach(chapter=>{
    (chapter.vocab||[]).forEach(card=>{
      const src=window.A2_VOCAB_21_IMAGES[chapter.num+'|'+card.w];
      if(src&&!card.img) card.img=src;
    });
  });
})();
